input.query:
WITH r0 AS (
  SELECT rp.target_iri AS prod FROM recall r JOIN recall__products rp ON rp.owner_iri = r.iri WHERE r.recall_number = 'D-0820-2021'
),
subs AS (
  SELECT DISTINCT pi.substance_iri AS s FROM product__ingredients pi WHERE pi.owner_iri IN (SELECT prod FROM r0)
),
prods AS (
  SELECT DISTINCT pi.owner_iri AS p FROM product__ingredients pi WHERE pi.substance_iri IN (SELECT s FROM subs)
)
SELECT r.recall_number, r.iri, rp.target_iri
FROM recall r JOIN recall__products rp ON rp.owner_iri = r.iri
WHERE rp.target_iri IN (SELECT p FROM prods) AND r.recall_number <> 'D-0820-2021'
ORDER BY r.recall_number;

