SELECT s.name, s.unii, m.name AS moiety, m.unii AS moiety_unii, sam.source
FROM substance__active_moiety sam JOIN substance s ON s.iri=sam.owner_iri JOIN substance m ON m.iri=sam.moiety_iri
WHERE m.unii='M801H13NRU' OR s.unii='M801H13NRU';

