input.query:
SELECT s.name, s.unii, m.name AS moiety, m.unii AS moiety_unii
FROM substance s LEFT JOIN substance__active_moiety am ON am.owner_iri=s.iri LEFT JOIN substance m ON m.iri=am.moiety_iri
WHERE s.name ILIKE '%diclofenac%' OR s.name ILIKE '%misoprostol%';

