input.query:
WITH labelers AS (
  SELECT DISTINCT pp.labeler_iri FROM packaged_product pp JOIN product p ON p.iri = pp.product_iri WHERE p.product_ndc = '68084-975'
),
labeled_products AS (
  SELECT DISTINCT pp.product_iri FROM packaged_product pp WHERE pp.labeler_iri IN (SELECT labeler_iri FROM labelers)
)
SELECT r.iri, r.recall_number, r.recalling_firm_iri, rp.target_iri
FROM recall r JOIN recall__products rp ON rp.owner_iri = r.iri
WHERE rp.target_iri IN (SELECT product_iri FROM labeled_products)
ORDER BY r.iri;

