input.query:
with s as (select iri from substance where unii='MZ1131787D'), o as (select iri from organization where name ilike 'Geri-Care%')
select o.iri, pp.ndc, p.product_ndc, p.name, pp.labeler_iri from o join packaged_product pp on pp.labeler_iri=o.iri join product p on p.iri=pp.product_iri
where exists(select 1 from product__ingredients i, s where i.owner_iri=p.iri and i.substance_iri=s.iri) limit 5;

