input.query:
SELECT p.product_ndc, p.name, s.name AS substance, s.iri
FROM product p JOIN product__ingredients pi ON pi.owner_iri=p.iri JOIN substance s ON s.iri=pi.substance_iri
WHERE p.product_ndc='11523-0165';

