input.query:
WITH rp AS (
  SELECT rp.target_iri AS product_iri FROM recall r JOIN recall__products rp ON rp.owner_iri = r.iri WHERE r.recall_number = 'D-0525-2026'
), labelers AS (
  SELECT DISTINCT pp.labeler_iri FROM packaged_product pp WHERE pp.product_iri IN (SELECT product_iri FROM rp)
), labeled_products AS (
  SELECT DISTINCT pp.product_iri FROM packaged_product pp WHERE pp.labeler_iri IN (SELECT labeler_iri FROM labelers)
)
SELECT s.iri, s.unii, s.name, count(DISTINCT lp.product_iri) AS n_products
FROM labeled_products lp
JOIN product__ingredients i ON i.owner_iri = lp.product_iri
JOIN substance s ON s.iri = i.substance_iri
GROUP BY s.iri, s.unii, s.name
ORDER BY s.name;

