input.query:
WITH rp AS (
  SELECT DISTINCT r2.target_iri AS product_iri FROM recall r JOIN recall__products r2 ON r2.owner_iri = r.iri WHERE r.recall_number = 'D-0043-2015'
),
labelers AS (
  SELECT DISTINCT pp.labeler_iri FROM packaged_product pp WHERE pp.product_iri IN (SELECT product_iri FROM rp)
),
prods AS (
  SELECT DISTINCT pp.product_iri FROM packaged_product pp WHERE pp.labeler_iri IN (SELECT labeler_iri FROM labelers)
)
SELECT DISTINCT s.iri, s.unii, s.name
FROM prods p JOIN product__ingredients i ON i.owner_iri = p.product_iri
JOIN substance s ON s.iri = i.substance_iri
ORDER BY s.name;

