input.query:
SELECT o.name, (SELECT count(*) FROM packaged_product pp WHERE pp.labeler_iri=o.iri) AS pkgs,
 (SELECT count(*) FROM recall r WHERE r.recalling_firm_iri=o.iri) AS recalls
FROM organization o WHERE o.name ILIKE '%carefusion 213%';

