input.query:
with recursive nodes as (
 select iri, 0 d from substance where unii='1NM3M2487K'
), edges as (
 select product_iri a, substance_iri b from (select p.iri product_iri, i.substance_iri from product p join product__ingredients i on i.owner_iri=p.iri) x
 union select p.iri, pk.labeler_iri from packaged_product pk join product p on p.iri=pk.product_iri
 union select r.iri, rp.target_iri from recall r join recall__products rp on rp.owner_iri=r.iri
 union select r.iri, r.recalling_firm_iri from recall r
 union select pk.iri, pk.product_iri from packaged_product pk
)
select 1;

