input.query:
with s as (select iri from substance where unii='1NM3M2487K'),
f as (select iri, name from organization where name ilike '%celcius%')
select 'sub' k, s.iri, null::text n from s union all select 'firm', iri, name from f;

with recursive g as (
 select iri as node, 0 as d from substance where unii='1NM3M2487K'
 union
 select x.n, g.d+1 from g join lateral (
   select pi.product_iri n from product__ingredients_view_dummy pi where false
 ) x on true where false
) select 1;

